// TH14 synthetic training aliases copied from transcribe/th14/touhou-bullets.ecl.
// Native type 0..23 -> modern same number; native 24..42 -> modern +1.
// Only the slots used by this card are copied.

// source type 5 (etSprite(0, 5, 6)): used by Phantom01_at and GirlD01_at children
const TH14_BALL2: int = 432;
// source type 19 (etSprite(0, 19, 3)): GirlD01_at parent bullets
const TH14_BIG_BALL2: int = 656;

// th14_s3_w12 - TH14 v1.00b st03.ecl MainSub07 (source lines 777-791).
// Card frame 0 = shell start; source frame 0 starts after OPENING_BUFFER.
// Source coordinates are relative to the stage caller at (0,0), so they are
// world coordinates here.

const TIME_LIMIT: int = 2724;
const OPENING_BUFFER: int = 120;

// ---------------------------------------------------------------------------
// Source: MainSub07.  @MainSub07b() async; @MainSub07c() async;
// wait(120); enmCreate GirlD01(0,-48); wait(300); enmCreate ECir00 pair.
// ---------------------------------------------------------------------------
async sub pattern() {
    wait(OPENING_BUFFER);
    spawn phantom_left();
    spawn phantom_right();
    wait(120);
    // GirlD01(0.0, -48.0), hp 1000
    _ = spawn_enemy(0fx, -48fx, 1000, 0, 0, 0, girld01_main);
    wait(300);
    // ECir00(96,-32) with source F0=pi, F1=-0.349066; ECir00(-96,-32) F0=0, F1=+0.349066
    // F0/F1 are inherited enemy slots in source; here they are task arguments.
    _ = spawn_enemy(96fx, -32fx, 240, 0, 0, 0, ecir00_main(32768, -3641));
    _ = spawn_enemy(-96fx, -32fx, 240, 0, 0, 0, ecir00_main(0, 3641));
    loop { wait(1000); }
}

// ---------------------------------------------------------------------------
// Source: MainSub07b (lines 793-804) - left Phantom01 group.
// $A=10; create at (-192, 64 + RANDF*128); wait(40).
// ---------------------------------------------------------------------------
async sub phantom_left() {
    for i in 0..10 {
        var y: fx = 64fx + ((rand(65536) * 128 / 65536) as fx);
        _ = spawn_enemy(-192fx, y, 130, 0, 0, 0, phantom_main(1));
        wait(40);
    }
}

// Source: MainSub07c (lines 806-818) - right Phantom01 group, enmCreateM.
// wait(20); $A=10; create at (192, 64 + RANDF*128); wait(40).
// Mirror (enmCreateM) only flips the linear moveVel direction (dir=-1);
// circular setters are not mirrored per circular-motion.md.
async sub phantom_right() {
    wait(20);
    for i in 0..10 {
        var y: fx = 64fx + ((rand(65536) * 128 / 65536) as fx);
        _ = spawn_enemy(192fx, y, 130, 0, 0, 0, phantom_main(-1));
        wait(40);
    }
}

// ---------------------------------------------------------------------------
// Source: Phantom01 (lines 832-857).
// setHurtbox(28,28)->14, setHitbox(16,16)->8;
// moveVel(0,1); moveCircleRel(RANDRAD, 1deg/frame, r=0, d=0);
// moveCircleRelTime(80, mode0 linear, omega keep, r 0->16, d 0).
// !HL @Phantom01_at() async; setDeath("Phantom01_at2") is !NHL but the shell
// never kills enemies (no player DPS), so the death burst is not synthesized.
// ---------------------------------------------------------------------------
async sub phantom_main(dir: int) {
    set_invuln(65535);
    set_hurtbox(14fx);
    set_hitbox(8fx);
    if global(GVAR_RANK) >= 2 {          // source !HL
        spawn phantom_fire();
    }
    var phase: angle = (rand(65536) - 32768) as angle;   // %RANDRAD
    var x0: fx = $self_x;
    var y0: fx = $self_y;
    var t: int = 0;
    loop {
        t = t + 1;
        var r: fx = 16fx * (t as fx) / 80fx;
        if t >= 80 { r = 16fx; }
        phase = phase + 1deg;
        move_to(0,
            x0 + (dir as fx) * (t as fx) + r * cos(phase),
            y0 + r * sin(phase),
            EASE_LINEAR);
        wait(1);
    }
}

// Source: Phantom01_at (lines 859-880). etAim(0,0) single aimed shot,
// type5 color6, speed 2.0, ANIM a=1 -> keep the -4*velocity birth shift.
// diffWait arguments are all evaluated in source: keep four RAND draws per
// wait even though only the current rank's value is used.
async sub phantom_fire() {
    var rank: int = global(GVAR_RANK);
    var we: int = 60 + rand(180);
    var wn: int = 60 + rand(40);
    var wh: int = 60 + rand(40);
    var wl: int = 40 + rand(40);
    var w: int = wl;
    if rank == 2 { w = wh; }
    wait(w);
    for i in 0..9 {                      // first etOn + 8 loop bodies (A=8 on Lunatic)
        if i > 0 {
            we = 30 + rand(40);
            wn = 30 + rand(40);
            wh = 60 + rand(20);
            wl = 60 + rand(20);
            w = wl;
            if rank == 2 { w = wh; }
            wait(w);
        }
        var ang: angle = aim_player();
        _ = fire(TH14_BALL2, 6,
            $self_x - 8fx * cos(ang), $self_y - 8fx * sin(ang),
            2fx, ang, none, none);
    }
}

