// Source: GirlD01_at (lines 319-374).
// wait(60); emitter: aim mode1 fan of 2, type19 color3, speed 0.2,
// EX: WAIT 120 then SHOOT (8 paths x 3 layers type5 color6, speed 3.0->0.9,
// r=RANDRAD, s=RANDRAD, delete parent). diffI B=2/4/6/8 volleys,
// etAngle(pi/2, A) with A starting pi/2 and -=15deg per volley,
// wait 40/20/13/10.
// The two parent bullets are tracked analytically: each splits 120 frames
// after birth at 24px along its own angle; both share the per-volley
// RANDRAD samples (source samples r/s once per volley on the emitter).
// ---------------------------------------------------------------------------
async sub girld01_at() {
    var rank: int = global(GVAR_RANK);
    var n: int = 8;
    if rank == 2 { n = 6; } else if rank == 1 { n = 4; } else if rank == 0 { n = 2; }
    var wt: int = 10;
    if rank == 2 { wt = 13; } else if rank == 1 { wt = 20; } else if rank == 0 { wt = 40; }
    wait(60);
    var spread: int = 16384;             // %A = pi/2
    for k in 0..n {
        var alpha: int = rand(65536) - 32768;   // SHOOT r = %RANDRAD
        var delta: int = rand(65536) - 32768;   // SHOOT s = %RANDRAD
        // mode1 fan, N=2: i=0 -> alpha+delta/2, i=1 -> alpha-delta/2
        var a0: int = 16384 + spread / 2;
        var a1: int = 16384 - spread / 2;
        var x0: fx = $self_x - 0.8fx * cos(a0 as angle);
        var y0: fx = $self_y - 0.8fx * sin(a0 as angle);
        var x1: fx = $self_x - 0.8fx * cos(a1 as angle);
        var y1: fx = $self_y - 0.8fx * sin(a1 as angle);
        _ = fire(TH14_BIG_BALL2, 3, x0, y0, 0.2fx, a0 as angle, GIRL_PARENT, none);
        _ = fire(TH14_BIG_BALL2, 3, x1, y1, 0.2fx, a1 as angle, GIRL_PARENT, none);
        spawn girl_children(119,
            x0 + 24fx * cos(a0 as angle), y0 + 24fx * sin(a0 as angle), alpha, delta);
        spawn girl_children(119,
            x1 + 24fx * cos(a1 as angle), y1 + 24fx * sin(a1 as angle), alpha, delta);
        spread = spread - 2731;          // %A -= 0.261799 rad (15 deg)
        wait(wt);
    }
}

// Parent bullet: source EX WAIT 120 then SHOOT_DATA deletes the parent.
// xform runs from the birth frame; the bullet task starts one frame later,
// so the task side waits 119 (documented off-by-one between sh_task/task and
// xformdef clocks).
xformdef GIRL_PARENT {
    wait(120);
    set_life(1);
}

// Source: GirlD01_at SHOOT effect, aim mode3 fixed ring: 8 paths x 3 layers,
// angle = alpha + i*65536/8 + j*delta, speed 3.0/1.95/0.9, type5 color6.
// Children copy parent EX at index 8 (ANIM a=1, sound): keep the -4*velocity
// birth shift, drop sound.
async sub girl_children(delay: int, px: fx, py: fx, alpha: int, delta: int) {
    wait(delay);
    for j in 0..3 {
        var sp: fx = 3fx - 1.05fx * (j as fx);
        var off: fx = 4fx * sp;
        for i in 0..8 {
            var ang: int = alpha + (i * 65536) / 8 + delta * j;
            _ = fire(TH14_BALL2, 6,
                px - off * cos(ang as angle), py - off * sin(ang as angle),
                sp, ang as angle, none, none);
        }
    }
}

// ---------------------------------------------------------------------------
// Source: ECir00 (lines 8-31). setHurtbox 24->12, setHitbox 16->8;
// moveVel(ANGLE_PLAYER, 3.0); moveSpeedTime(40, mode1)->0; wait(40);
// @ECir00_at(F0) async; wait(60); moveVel(ANGLE_PLAYER, 0.0);
// moveSpeedTime(120, mode1)->2.0; infinite wait.
// ---------------------------------------------------------------------------
async sub ecir00_main(f0: int, f1: int) {
    set_invuln(65535);
    set_hurtbox(12fx);
    set_hitbox(8fx);
    move_vel(0, aim_player(), 3fx, EASE_LINEAR);
    move_speed(40, 0fx, EASE_QUAD_IN);
    wait(40);
    spawn ecir00_lasers(f0, f1);
    wait(60);
    move_vel(0, aim_player(), 0fx, EASE_LINEAR);
    move_speed(120, 2fx, EASE_QUAD_IN);
    loop { wait(1000); }
}

// Source: ECir00_at (lines 33-87): etAngle(A, 0); A += F1; laserOn;
// wait 7/5/4/4; B = 11/16/20/24.
// laserNew(0, initial 0, target 160, limit 0, width 14) with emitter speed 5.
// Target: constant-width growing rod; native Line hit segment is
// [0.1L, 0.9L] = [16,144] once grown, rod length 0.8*160 = 128, growth/travel
// speed from etSpeed = 5px/frame (laser_approx=true, see report.md).
async sub ecir00_lasers(a0: int, step: int) {
    var rank: int = global(GVAR_RANK);
    var n: int = 24;
    if rank == 2 { n = 20; } else if rank == 1 { n = 16; } else if rank == 0 { n = 11; }
    var wt: int = 4;
    if rank == 1 { wt = 5; } else if rank == 0 { wt = 7; }
    var a: int = a0;
    for k in 0..n {
        var h: int = laser(3, $self_x, $self_y, a as angle, 0fx, 7fx, 0, 180, 0);
        lz_start(h, 16fx);
        lz_speed(h, 5fx, 128fx);
        a = a + step;
        wait(wt);
    }
}

